params.command:
$ErrorActionPreference='Stop'
$r='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
$wt='C:\Users\Xxkan\HeavenBridge\verify-pr137'
git -C $r fetch origin --prune | Out-Null
if(Test-Path $wt){git -C $r worktree remove --force $wt 2>$null | Out-Null}
git -C $r worktree prune | Out-Null
git -C $r worktree add --detach $wt origin/integration/launch-observation-atomicity-main-20260929 | Out-Host
if($LASTEXITCODE -ne 0){throw 'worktree add failed'}
try {
  Write-Output ('HEAD='+(git -C $wt rev-parse HEAD).Trim())
  git -C $wt diff --check origin/main...HEAD
  if($LASTEXITCODE -ne 0){throw 'git diff --check failed'}
  dotnet test (Join-Path $wt 'tests\MhwModManager.AutomationTests\MhwModManager.AutomationTests.csproj') -c Release --filter 'FullyQualifiedName~LaunchObservationRepositoryTests' --no-restore
  if($LASTEXITCODE -ne 0){throw 'targeted launch observation tests failed'}
  dotnet build (Join-Path $wt 'src\MhwModManager.App\MhwModManager.App.csproj') -c Release --no-restore
  if($LASTEXITCODE -ne 0){throw 'app build failed'}
  Write-Output 'PR137_TARGETED_GATE_OK'
} finally {
  git -C $r worktree remove --force $wt 2>$null | Out-Null
  git -C $r worktree prune | Out-Null
}
